/**
 * @eigenpal/docx-editor-i18n/ru
 *
 * Русский (`ru`) — прямой подпуть локали для разделения кода по локалям.
 *
 * ```ts
 * // Статическая загрузка — сборщик включает только строки этой локали
 * import ru from '@eigenpal/docx-editor-i18n/ru';
 *
 * // Динамическая загрузка — выделяется в отдельный чанк, загружается по требованию
 * const ru = (await import('@eigenpal/docx-editor-i18n/ru')).default;
 * ```
 *
 * Для приложений с несколькими локалями предпочтительнее использовать подпути отдельных локалей,
 * а не импортировать `locales` из корня пакета — импорт `locales` загружает все локали в сборку.
 *
 * @packageDocumentation
 * @public
 */
import { LocaleStrings } from './index.js';

/**
 * Русская (`ru`) локаль — исходный эталон, покрытая на 100%.
 *
 * Содержимое идентично именованному экспорту `ru` из корня пакета;
 * этот подпуть просто позволяет сборщикам разделить его на отдельные чанки.
 *
 * @public
 */
declare const ru: LocaleStrings;

export { ru as default, ru };
